import {updateCombustionProcedure} from './combustion-procedure.js';
import {highlightNext} from './combustion-guidance.js';
import {mountCombustion,shelfTarget} from './combustion-workbench.js';
import {combustionRecordsMarkup} from './combustion-records.js';
import {metals,nonmetals} from './model.js';
import {sampleVisual} from './specimens.js';
import {bindDrop} from './direct-manipulation.js';
import {materialCases} from './journey-cards.js';
import {bottleSolutions} from './bottle-ph-state.js';
// Keep the historical :ph evidence key for completed saved bottle observations.
export function sampleIcon(key,prefix='tray-'){return sampleVisual(key==='CO'?'C':key,false,true,prefix+key,{form:{Mg:'ribbon',Cu:'sheet',Zn:'powder',Na:'block',S:'powder',P:'powder'}[key]});}
export function mountBurn(root,c,ctx,{demonstration=false}={}){
 const {s,has,record,notice,delay}=ctx,key=s.selected,isMetal=!!metals[key],d=isMetal?metals[key]:nonmetals[key];
 if(!demonstration)updateCombustionProcedure(root,key);
 let apparatus=null,localBurned=false,localCool=true,running=false,localPoint=null;const burned=()=>localBurned,cooled=()=>localCool;
 root.innerHTML=`<div class="combustion-studio integrated-studio" aria-label="樣本架與燃燒實驗台" id="combustion-studio" tabindex="-1"><div class="specimen-shelf"></div><div class="bench-workspace"><div class="bench-sequence"><span data-process="burn">1 取樣與燃燒</span><i>→</i><span data-process="water">2 產物入水</span><i>→</i><span data-process="litmus">3 比較酸鹼性</span></div><p class="experiment-purpose" data-stage-purpose></p><div class="burn-content"></div></div></div><div class="comparison-sheet"></div>`;
 const content=root.querySelector('.burn-content'),sheet=root.querySelector('.comparison-sheet');
 function nextSample(){const cases=materialCases[c.type];const ordered=c.type==='combustion'?[...['Na','S'].map(id=>cases.find(([key])=>key===id)),...cases.filter(([key])=>!['Na','S'].includes(key))]:cases;return ordered.find(([key])=>!has(key+(bottleSolutions[key]?':ph':':wet')));}
 function table(){sheet.innerHTML=combustionRecordsMarkup(c.type,has);}
 function setProcess(phase){for(const step of root.querySelectorAll('[data-process]')){const active=step.dataset.process===phase;step.classList.toggle('current-process',active);if(active)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current');}}
 function renderBurn(replay=false){root.querySelector('[data-stage-purpose]').textContent='在同一台追蹤：燃燒 → 產物遇水 → 石蕊試紙觀察酸鹼性。';if(replay){localBurned=false;localCool=true;}s.tab='burn';content.innerHTML='<div data-combustion-mount></div>';apparatus=mountCombustion(content.querySelector('[data-combustion-mount]'),{key,isMetal,externalClock:demonstration,autoLoad:!!s.autoLoad,spoonOrigin:burned()?localPoint:s.spoonOrigin,onCleanup:ctx.onCleanup,onProcessChange:setProcess,completed:burned()&&!replay,cool:cooled(),token:sampleIcon(key),name:d.name,delay,notice,onStart:()=>{running=true;},onComplete:point=>{localPoint=point;running=false;localBurned=true;record(key+':burn');if(key==='Zn')record('Zn:cool');renderBurn();table();},onCool:()=>{localPoint=[400,335];localCool=true;record('Zn:cool');renderBurn();table();},onWetComplete:()=>{record(key+(bottleSolutions[key]?':ph':':wet'));table();setProcess('complete');if(demonstration)return;content.querySelector('.sample-complete-actions')?.remove();const next=nextSample();const actions=document.createElement('div');actions.className='sample-complete-actions';actions.innerHTML='<b>這份樣本的兩張試紙都測好了。</b>'+(next?'<button type="button" class="primary" data-next-burn-sample>'+(c.type==='combustion'&&!['Na','S'].includes(next[0])?'選做延伸：':'換下一個樣本：')+next[1]+' →</button>':'<span>可以對照下方的樣本紀錄。</span>');content.append(actions);actions.querySelector('[data-next-burn-sample]')?.addEventListener('click',()=>ctx.setCase(next[0],false));if(next)highlightNext(root,{id:'next-sample',tool:'[data-shelf-sample="'+next[0]+'"]',label:'下一份樣本'});}});s.autoLoad=false;s.spoonOrigin=null;renderShelf();const board=root.querySelector('.combustion-workbench');if(board?.dataset.combustionStage==='load'){const next=demonstration?[key,d.name]:nextSample();highlightNext(root,next?{id:'load',tool:'[data-shelf-sample="'+next[0]+'"]',label:c.type==='combustion'&&!['Na','S'].includes(next[0])?'選做延伸樣本':'拿取下一個樣本'}:{id:'complete'});}}
 function renderShelf(){const shelf=root.querySelector('.specimen-shelf');shelf.hidden=false;if(c.type!=='combustion'){shelf.hidden=true;return;}shelf.innerHTML='<div class="shelf-heading"><b>鐵匠的樣本架</b><span>抓取樣本 → 放上燃燒匙</span></div>'+[['metals','金屬','metals'],['nonmetals','非金屬','nonmetals']].map(([type,title,group])=>'<section class="specimen-group '+group+'" aria-label="'+title+'樣本"><h4>'+title+'<small>'+ (group==='metals'?'鈉・鎂・鋅・銅':'硫・紅磷・碳')+'</small></h4><div class="shelf-rail">'+materialCases[type].map(([k,label])=>'<div class="shelf-specimen '+(key===k?'selected':'')+'" data-shelf-sample="'+k+'" aria-label="'+label+'樣本"><div class="specimen-vial">'+sampleIcon(k)+'</div><b>'+label+'</b><small>'+ (has(k+':burn')?'✓ 已觀察':'拖曳取用')+'</small></div>').join('')+'</div></section>').join('');for(const item of shelf.querySelectorAll('[data-shelf-sample]'))bindDrop(item,()=>shelfTarget(root.querySelector('.combustion-workbench')),{onDrop:()=>{const target=shelfTarget(root.querySelector('.combustion-workbench'));ctx.setCase(item.dataset.shelfSample,true,[Number(target.dataset.spoonX),Number(target.dataset.spoonY)]);},onMiss:()=>notice('對準眼前燃燒匙的凹槽，匙口亮起後再放開；不用回到最初的位置。')});}

 renderBurn();table();
 return {get apparatus(){return apparatus;},load(){s.autoLoad=true;renderBurn();}};
}
